def prepare_conditioning(time_emb, class_emb):
    """Hybrid FiLM + Cross-Attention conditioning.

    Combines class embedding with time embedding (FiLM pathway) so that
    class information flows through the ResBlock timestep conditioning.
    Additional conditioning is provided via cross-attention in ClassConditioner.
    """
    return time_emb + class_emb


class ClassConditioner(nn.Module):
    """Cross-attention conditioning applied after each UNet block.

    Works in tandem with FiLM conditioning from prepare_conditioning.
    """
    def __init__(self, channels, cond_dim):
        super().__init__()
        self.cross_attn = CrossAttentionLayer(channels, cond_dim, num_heads=4)

    def forward(self, h, class_emb):
        return self.cross_attn(h, class_emb)

def prepare_conditioning(time_emb, class_emb):
    """Class-conditioned time embedding via learned affine modulation."""
    # Modulate time embedding with class info
    return time_emb * (1 + class_emb * 0.01)


class ClassConditioner(nn.Module):
    """Cross-attention followed by adaptive scale modulation."""
    def __init__(self, channels, cond_dim):
        super().__init__()
        self.cross_attn = CrossAttentionLayer(channels, cond_dim, num_heads=4)
        self.scale = zero_module(nn.Linear(cond_dim, channels))
        self.shift = zero_module(nn.Linear(cond_dim, channels))

    def forward(self, h, class_emb):
        h = self.cross_attn(h, class_emb)
        s = self.scale(class_emb).unsqueeze(-1).unsqueeze(-1)
        sh = self.shift(class_emb).unsqueeze(-1).unsqueeze(-1)
        return h * (1 + s) + sh
